def each_discount_a_row(apps, schema_editor):
    Invoice = apps.get_model("sales", "Invoice")
    InvoiceDiscount = apps.get_model("sales", "InvoiceDiscount")
    taken = Invoice.objects.filter(settlement_discount_entry__isnull=False, settlement_discount_amount__gt=0)
    for document in taken.select_related("settlement_discount_entry").order_by("pk"):
        InvoiceDiscount.objects.create(
            invoice=document, payment=None, date=document.settlement_discount_entry.date,
            amount=document.settlement_discount_amount, journal_entry=document.settlement_discount_entry,
            withdrawn_amount=document.settlement_discount_withdrawn,
            withdrawal_entry_id=document.settlement_discount_withdrawal_entry_id,
        )


def back_to_one_a_document(apps, schema_editor):
    """Back to one discount a document: refused where a document holds two, which the old fields cannot say."""
    Invoice = apps.get_model("sales", "Invoice")
    InvoiceDiscount = apps.get_model("sales", "InvoiceDiscount")
    rows = list(InvoiceDiscount.objects.order_by("invoice_id", "pk"))
    seen = set()
    for row in rows:
        if row.invoice_id in seen:
            raise RuntimeError(f"Invoice {row.invoice_id} has more than one settlement discount; the fields this "
                               "goes back to keep one.")
        seen.add(row.invoice_id)
        Invoice.objects.filter(pk=row.invoice_id).update(
            settlement_discount_entry_id=row.journal_entry_id,
            settlement_discount_withdrawal_entry_id=row.withdrawal_entry_id)


